body:not(.site-theme-dark) {
  color-scheme: light;
  --color-blue-dim: 165.43453836, 112.33691589, 234.66308411;
  --color-background: 220, 224, 232;
  --color-foreground: 239, 241, 245;
  --color-foreground-grey: 204, 208, 218;
  --color-foreground-grey-dark: 189.22159091, 194.38068182, 207.27840909;
  --color-foreground-blue: 230, 233, 239;
  --color-foreground-blue-dark: 230, 233, 239;
  --color-background-blue-dark: 92, 95, 119;
  --color-overlay: 204, 208, 218;
  --color-shadow: 230, 233, 239;
  --color-shadow-dark: 54.58563536, 56.74033149, 75.41436464;
  --color-shadow-blue: 30, 102, 245;
  --color-text: 76, 79, 105;
  --color-text-light: 92, 95, 119;
  --color-text-lighter: 108, 111, 133;
  --color-text-bright: 220, 224, 232;
  --color-blue: 136, 57, 239;
  --color-white: 255, 255, 255;
  --color-black: 0, 0, 0;
  --color-red: 210, 15, 57;
  --color-peach: 230, 69, 83;
  --color-orange: 254, 100, 11;
  --color-yellow: 223, 142, 29;
  --color-green: 64, 160, 43;
  --color-background-1200: 76, 79, 105;
